
/* =========================================================
   MiniChart.js — lightweight Chart.js-compatible API
   Implements: line, bar, doughnut, radar
   No external dependencies whatsoever.
   ========================================================= */
class Chart {
  constructor(ctx, config) {
    this.ctx = ctx;
    this.config = config;
    this.canvas = ctx.canvas;
    this._destroyed = false;
    this._instances = Chart._instances || (Chart._instances = new Map());
    this._instances.set(ctx.canvas.id || Math.random(), this);
    requestAnimationFrame(() => this.draw());
  }

  destroy() { this._destroyed = true; }

  _color(c, alpha) {
    if (!c) return `rgba(100,100,100,${alpha})`;
    if (c.startsWith('rgba')) return c;
    if (c.startsWith('rgb(')) return c.replace('rgb(', 'rgba(').replace(')', `,${alpha})`);
    if (c.startsWith('#')) {
      const r = parseInt(c.slice(1,3),16), g = parseInt(c.slice(3,5),16), b = parseInt(c.slice(5,7),16);
      return `rgba(${r},${g},${b},${alpha})`;
    }
    return c;
  }

  _W() { return this.canvas.offsetWidth || this.canvas.width || 300; }
  _H() { return this.canvas.offsetHeight || this.canvas.height || 200; }

  draw() {
    if (this._destroyed) return;
    const c = this.ctx, type = this.config.type;
    const W = this._W(), H = this._H();
    this.canvas.width = W; this.canvas.height = H;
    c.clearRect(0, 0, W, H);
    c.save();
    if      (type === 'line')     this._drawLine(c, W, H);
    else if (type === 'bar')      this._drawBar(c, W, H);
    else if (type === 'doughnut') this._drawDoughnut(c, W, H);
    else if (type === 'radar')    this._drawRadar(c, W, H);
    c.restore();
  }

  _pad() { return { t:16, r:18, b:32, l:46 }; }

  // Shared number formatter — only abbreviates to 'k' above 10,000 so that
  // typical yield ranges (hundreds to low-thousands) stay distinct instead
  // of collapsing multiple ticks onto the same rounded label.
  _fmtNum(val) {
    const v = Math.abs(val) < 0.05 ? 0 : val;
    if (Math.abs(v) >= 10000) return (Math.round(v/100)/10) + 'k';
    return Math.round(v).toLocaleString('en-IN');
  }

  _range(vals) {
    const flat = [].concat(...vals.map(v => Array.isArray(v) ? v : [v])).filter(v=>v!=null);
    if (!flat.length) return { mn:0, mx:100 };
    let mn = Math.min(...flat), mx = Math.max(...flat);
    if (mn === mx) { mn -= 1; mx += 1; }
    const pad = (mx - mn) * 0.1;
    return { mn: mn - pad, mx: mx + pad };
  }

  _labels() { return (this.config.data || {}).labels || []; }
  _sets()   { return ((this.config.data || {}).datasets || []); }

  _drawGrid(c, x0, y0, x1, y1, labels, mn, mx, steps=5) {
    c.strokeStyle = 'rgba(200,190,175,0.45)';
    c.lineWidth = 0.8;
    c.setLineDash([4,4]);
    for (let i=0; i<=steps; i++) {
      const y = y0 + (y1-y0)*(i/steps);
      c.beginPath(); c.moveTo(x0,y); c.lineTo(x1,y); c.stroke();
      const val = mx - (mx-mn)*(i/steps);
      c.fillStyle = '#5A4530'; c.font = '9px Inter,sans-serif';
      c.textAlign = 'right';
      c.fillText(this._fmtNum(val), x0-5, y+3);
    }
    // zero baseline (drawn solid, slightly stronger) when the range crosses 0
    if (mn < 0 && mx > 0) {
      const zy = y1 - (y1-y0)*((0-mn)/(mx-mn||1));
      c.setLineDash([]);
      c.strokeStyle = 'rgba(90,69,48,0.5)'; c.lineWidth = 1;
      c.beginPath(); c.moveTo(x0,zy); c.lineTo(x1,zy); c.stroke();
    }
    c.setLineDash([]);
    // x grid lines — thin labels out so they never overlap
    const avgCharW = 5.3;
    const longest = Math.max(...labels.map(l => String(l).length), 1);
    const labelSlotW = (x1-x0) / Math.max(labels.length-1, 1);
    const skip = Math.max(1, Math.ceil((longest*avgCharW + 10) / Math.max(labelSlotW,1)));
    labels.forEach((lbl, i) => {
      const x = x0 + (x1-x0)*(i/(labels.length-1||1));
      c.beginPath(); c.strokeStyle='rgba(200,190,175,0.25)';
      c.moveTo(x,y0); c.lineTo(x,y1); c.stroke();
      const showLabel = (i % skip === 0) || i === labels.length-1;
      if (!showLabel) return;
      c.fillStyle='#5A4530'; c.font='9px Inter,sans-serif';
      c.textAlign = i === labels.length-1 ? 'right' : (i===0 ? 'left' : 'center');
      const shortLbl = typeof lbl==='string' && lbl.length>8 ? lbl.slice(0,7)+'…' : lbl;
      c.fillText(shortLbl, x, y1+14);
    });
  }

  _drawLine(c, W, H) {
    const pd = this._pad(), labels = this._labels(), sets = this._sets();
    const x0=pd.l, y0=pd.t, x1=W-pd.r, y1=H-pd.b;
    const allVals = sets.map(s => s.data || []);
    const {mn, mx} = this._range(allVals);
    this._drawGrid(c, x0, y0, x1, y1, labels, mn, mx);
    const toX = i => x0 + (x1-x0)*(i/(labels.length-1||1));
    const toY = v => y1 - (y1-y0)*((v-mn)/(mx-mn||1));
    sets.forEach(set => {
      const data = set.data || [], col = set.borderColor || '#4A6B3A';
      const bg = set.backgroundColor;
      const pts = data.map((v,i) => ({x:toX(i), y:toY(v)}));
      if (pts.length < 2) return;
      // Fill area
      if (bg && typeof bg !== 'function') {
        c.beginPath();
        c.moveTo(pts[0].x, y1);
        pts.forEach(p => c.lineTo(p.x, p.y));
        c.lineTo(pts[pts.length-1].x, y1);
        c.closePath();
        c.fillStyle = typeof bg === 'string' ? bg : 'rgba(74,107,58,0.1)';
        c.fill();
      }
      // Smooth line
      c.beginPath(); c.strokeStyle = col; c.lineWidth = 2.5; c.lineJoin='round'; c.lineCap='round';
      const t = set.tension || 0;
      if (t > 0) {
        c.moveTo(pts[0].x, pts[0].y);
        for (let i=0; i<pts.length-1; i++) {
          const cx1=pts[i].x+(pts[i+1].x-pts[i].x)*t;
          const cx2=pts[i+1].x-(pts[i+1].x-pts[i].x)*t;
          c.bezierCurveTo(cx1,pts[i].y,cx2,pts[i+1].y,pts[i+1].x,pts[i+1].y);
        }
      } else {
        pts.forEach((p,i) => i===0 ? c.moveTo(p.x,p.y) : c.lineTo(p.x,p.y));
      }
      c.stroke();
      // Points
      const pr = set.pointRadius || 4;
      if (pr > 0) {
        pts.forEach((p,i) => {
          c.beginPath(); c.arc(p.x, p.y, pr, 0, Math.PI*2);
          const pBg = Array.isArray(set.pointBackgroundColor) ? set.pointBackgroundColor[i] : (set.pointBackgroundColor||col);
          c.fillStyle = pBg; c.fill();
          c.strokeStyle = set.pointBorderColor||'#fff'; c.lineWidth=set.pointBorderWidth||2; c.stroke();
        });
      }
    });
    // Legend
    this._drawLegend(c, W, sets);
    // Title
    this._drawTitle(c, W);
  }

  _drawBar(c, W, H) {
    const pd = this._pad(), labels = this._labels(), sets = this._sets();
    const isH = (this.config.options||{}).indexAxis === 'y';
    const x0=pd.l+(isH?20:0), y0=pd.t, x1=W-pd.r, y1=H-pd.b;
    const allVals = sets.map(s=>s.data||[]);
    const {mn,mx} = this._range([[0],...allVals]);
    if (!isH) {
      this._drawGrid(c, x0, y0, x1, y1, labels, mn, mx);
      const bw = (x1-x0)/Math.max(labels.length,1)*0.6;
      const gap = (x1-x0)/Math.max(labels.length,1);
      const zeroY = y1 - (y1-y0)*((0-mn)/(mx-mn||1));
      sets.forEach((set,si) => {
        const data=set.data||[], col=set.backgroundColor;
        data.forEach((v,i) => {
          const x = x0 + gap*i + gap*0.2 + si*(bw/sets.length);
          const barW = bw/sets.length;
          const valY = y1 - (y1-y0)*((v-mn)/(mx-mn||1));
          const barY = Math.min(zeroY, valY);
          const barH = Math.max(Math.abs(zeroY - valY), 1);
          const r = set.borderRadius||4;
          const clr = Array.isArray(col)?col[i]:(col||'#4A6B3A');
          c.fillStyle = clr;
          c.beginPath();
          c.roundRect ? c.roundRect(x,barY,barW,barH,Math.min(r,barH/2)) : c.rect(x,barY,barW,barH);
          c.fill();
        });
      });
    } else {
      // Horizontal bar
      const px0=x0+40, py0=y0, px1=x1, py1=y1;
      const barH = (py1-py0)/Math.max(labels.length,1)*0.55;
      const gap = (py1-py0)/Math.max(labels.length,1);
      const maxV = Math.max(...(sets[0]?.data||[0]),1);
      labels.forEach((lbl,i) => {
        const y = py0 + gap*i + gap*0.2;
        const v = (sets[0]?.data||[])[i]||0;
        const bw = (px1-px0)*(v/maxV);
        const col = Array.isArray(sets[0]?.backgroundColor)?sets[0].backgroundColor[i]:(sets[0]?.backgroundColor||'#4A6B3A');
        c.fillStyle=col;
        c.beginPath();
        c.roundRect?c.roundRect(px0,y,bw,barH,3):c.rect(px0,y,bw,barH);
        c.fill();
        c.fillStyle='#5A4530'; c.font='9.5px Inter,sans-serif'; c.textAlign='right';
        const shortLbl = lbl.length>12?lbl.slice(0,11)+'…':lbl;
        c.fillText(shortLbl, px0-4, y+barH/2+3.5);
        c.fillStyle='#1E1208'; c.font='8.5px Inter,sans-serif'; c.textAlign='left';
        c.fillText(this._fmtNum(v), px0+bw+4, y+barH/2+3.5);
      });
      // x axis
      c.fillStyle='#5A4530'; c.font='9px Inter,sans-serif'; c.textAlign='center';
      for(let i=0;i<=5;i++){
        const x=px0+(px1-px0)*(i/5);
        const v=Math.round(maxV*(i/5));
        c.fillText(this._fmtNum(v), x, py1+14);
        c.strokeStyle='rgba(200,190,175,0.3)'; c.lineWidth=0.6; c.setLineDash([3,3]);
        c.beginPath(); c.moveTo(x,py0); c.lineTo(x,py1); c.stroke(); c.setLineDash([]);
      }
    }
    this._drawLegend(c,W,sets);
    this._drawTitle(c,W);
  }

  _drawDoughnut(c, W, H) {
    const sets=this._sets(), data=(sets[0]||{}).data||[], labels=this._labels();
    const colors=((sets[0]||{}).backgroundColor)||['#D4A017','#4A6B3A','#3D7FA6','#B8421F','#8B4513','#6B5A2A'];
    const cx=W/2, cy=H/2-10;
    const cutout = parseFloat((this.config.options||{}).cutout||'55%')/100;
    const r=Math.min(W,H)*0.36, ri=r*cutout;
    const total=data.reduce((a,b)=>a+b,0)||1;
    let angle=-Math.PI/2;
    data.forEach((v,i)=>{
      const slice=(v/total)*Math.PI*2;
      c.beginPath(); c.moveTo(cx,cy);
      c.arc(cx,cy,r,angle,angle+slice);
      c.closePath();
      c.fillStyle=Array.isArray(colors)?colors[i%colors.length]:'#888';
      c.fill();
      c.strokeStyle='rgba(253,250,244,0.9)'; c.lineWidth=3; c.stroke();
      // Label in slice
      if (slice > 0.35) {
        const mid=angle+slice/2;
        const lx=cx+Math.cos(mid)*(r+ri)/2, ly=cy+Math.sin(mid)*(r+ri)/2;
        c.fillStyle='#fff'; c.font='bold 9px Inter,sans-serif'; c.textAlign='center';
        c.fillText(`${Math.round(v/total*100)}%`, lx, ly+3);
      }
      angle+=slice;
    });
    // Inner circle cutout
    c.beginPath(); c.arc(cx,cy,ri,0,Math.PI*2);
    c.fillStyle=(this.config.options?.plugins?.legend?.labels?.color)?'rgba(253,250,244,0.95)':'rgba(253,250,244,0.95)';
    c.fill();
    // Legend on right
    const legendX=cx+r+14, legendY=cy-labels.length*10;
    labels.forEach((lbl,i)=>{
      const y=legendY+i*20;
      c.fillStyle=Array.isArray(colors)?colors[i%colors.length]:'#888';
      c.beginPath(); c.arc(legendX+6,y+5,5,0,Math.PI*2); c.fill();
      c.fillStyle='#5A4530'; c.font='10px Inter,sans-serif'; c.textAlign='left';
      const shortLbl=lbl.length>12?lbl.slice(0,11)+'…':lbl;
      c.fillText(shortLbl, legendX+14, y+9);
    });
    this._drawTitle(c,W);
  }

  _drawRadar(c, W, H) {
    const sets=this._sets(), labels=this._labels();
    const cx=W/2, cy=H/2+5, r=Math.min(W,H)*0.34;
    const n=labels.length; if(!n)return;
    const allVals=sets.flatMap(s=>s.data||[]);
    const mx=Math.max(...allVals,1);
    // Grid
    for(let ring=1;ring<=5;ring++){
      c.beginPath(); c.strokeStyle='rgba(200,190,175,0.4)'; c.lineWidth=0.7;
      for(let i=0;i<n;i++){
        const a=(i/n)*Math.PI*2-Math.PI/2;
        const x=cx+Math.cos(a)*r*(ring/5), y=cy+Math.sin(a)*r*(ring/5);
        i===0?c.moveTo(x,y):c.lineTo(x,y);
      }
      c.closePath(); c.stroke();
    }
    // Spokes
    for(let i=0;i<n;i++){
      const a=(i/n)*Math.PI*2-Math.PI/2;
      c.beginPath(); c.strokeStyle='rgba(200,190,175,0.4)'; c.lineWidth=0.7;
      c.moveTo(cx,cy); c.lineTo(cx+Math.cos(a)*r, cy+Math.sin(a)*r); c.stroke();
      // Labels
      const lx=cx+Math.cos(a)*(r+22), ly=cy+Math.sin(a)*(r+22);
      c.fillStyle='#5A4530'; c.font='10px Inter,sans-serif'; c.textAlign='center';
      c.fillText(labels[i], lx, ly+4);
    }
    // Data
    sets.forEach(set=>{
      const data=set.data||[], col=set.borderColor||'#4A6B3A';
      c.beginPath();
      for(let i=0;i<n;i++){
        const a=(i/n)*Math.PI*2-Math.PI/2;
        const v=Math.min(data[i]||0,mx)/mx;
        const x=cx+Math.cos(a)*r*v, y=cy+Math.sin(a)*r*v;
        i===0?c.moveTo(x,y):c.lineTo(x,y);
      }
      c.closePath();
      c.fillStyle=set.backgroundColor||'rgba(74,107,58,0.15)'; c.fill();
      c.strokeStyle=col; c.lineWidth=2.5; c.stroke();
      // Points
      for(let i=0;i<n;i++){
        const a=(i/n)*Math.PI*2-Math.PI/2;
        const v=Math.min(data[i]||0,mx)/mx;
        const x=cx+Math.cos(a)*r*v, y=cy+Math.sin(a)*r*v;
        c.beginPath(); c.arc(x,y,4,0,Math.PI*2);
        c.fillStyle=col; c.fill();
        c.strokeStyle='#fff'; c.lineWidth=1.5; c.stroke();
      }
    });
    this._drawTitle(c,W);
  }

  _drawLegend(c, W, sets) {
    const pos = (this.config.options?.plugins?.legend?.position||'bottom');
    if ((this.config.options?.plugins?.legend?.display)===false) return;
    if (pos!=='bottom') return;
    const H = this._H();
    let x = 20; const y = H-12;
    sets.forEach(set=>{
      const col = Array.isArray(set.borderColor)?set.borderColor[0]:set.borderColor||
                  Array.isArray(set.backgroundColor)?set.backgroundColor[0]:set.backgroundColor||'#888';
      c.fillStyle=col; c.beginPath(); c.arc(x+5,y-3,5,0,Math.PI*2); c.fill();
      c.fillStyle='#5A4530'; c.font='9.5px Inter,sans-serif'; c.textAlign='left';
      c.fillText(set.label||'', x+13, y+1);
      x += (set.label||'').length*6+28;
    });
  }

  _drawTitle(c, W) {
    const t=this.config.options?.plugins?.title;
    if (!t?.display) return;
    c.fillStyle=t.color||'#1E1208'; c.font=`bold ${t.font?.size||12}px Inter,sans-serif`;
    c.textAlign='center'; c.fillText(t.text||'', W/2, 18);
  }

  update() { this.draw(); }
}
Chart._instances = new Map();
window.Chart = Chart;
